def evaluate_D(N):
    min_D = float('inf')
    for m in range(1, N):
        for n in range(m + 1, N + 1):
            # x_i = i^2. x_n^2 - x_m^2 = n^4 - m^4
            term = (m + n) * (n**4 - m**4)
            if term < min_D:
                min_D = term
    return min_D

# We use N=27 as 27^2 = 729 <= 777, and 28^2 = 784 > 777.
max_N = 27
min_d_45 = evaluate_D(max_N)
print(f"Minimum D for x_i = i^2 up to N={max_N}: {min_d_45}")

